    Set-B2PSValue 'APP_MODE' 'development' -Export
} -Required

# Bash line 6

Invoke-B2PSStep {
    foreach ($b2psPath in @((Get-B2PSValue 'PROJECT'))) { if (Test-Path -LiteralPath $b2psPath -PathType Container) { continue }; New-Item -ItemType Directory -Path $b2psPath | Out-Null }
} -Required

# Bash line 7

Invoke-B2PSStep {
    Set-Location -LiteralPath (Get-B2PSValue 'PROJECT')
} -Required

