Invoke-B2PSStep {
    Write-B2PSText -Path '.env' -Lines @(Write-Output @('APP_MODE=development'))
} -Required

# Bash line 9

Invoke-B2PSStep {
    Update-B2PSFile -Paths @('README.md')
} -Required

# Bash line 10

Invoke-B2PSStep {
    Assert-B2PSTest (Test-Path -LiteralPath '.env' -PathType Leaf)
}

if ($script:B2PSStatus -eq 0) {
    Invoke-B2PSStep {
        Write-Output ((@('Config created')) -join ' ')
    } -Required
}

